WITH filtered_order_items AS (SELECT * FROM order_items WHERE product_id IS NOT NULL AND product_id = 36), summary AS (SELECT CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END AS quantity_bucket, MAX(quantity) AS max_quantity, MIN(unit_price) AS min_unit_price FROM filtered_order_items GROUP BY CASE WHEN quantity >= 7 THEN 'high' WHEN quantity >= 3 THEN 'mid' ELSE 'low' END) SELECT quantity_bucket, max_quantity, min_unit_price FROM summary
